def transform(grid):
    """Replace all cells in uniform rows or uniform columns with 2."""
    rows = len(grid)
    cols = len(grid[0])

    # Find uniform rows
    uniform_rows = set()
    for r in range(rows):
        first_val = grid[r][0]
        if all(grid[r][c] == first_val for c in range(cols)):
            uniform_rows.add(r)

    # Find uniform columns
    uniform_cols = set()
    for c in range(cols):
        first_val = grid[0][c]
        if all(grid[r][c] == first_val for r in range(rows)):
            uniform_cols.add(c)

    # Apply transformation
    result = []
    for r in range(rows):
        out_row = []
        for c in range(cols):
            if r in uniform_rows or c in uniform_cols:
                out_row.append(2)
            else:
                out_row.append(grid[r][c])
        result.append(out_row)

    return result

